<script setup>
import {computed} from 'vue'
const props=defineProps({chart:Object,diagram:String})
const plot=computed(()=>{const c=props.chart;if(!c||c.labels?.length!==c.values?.length||!c.values?.length||!c.values.every(Number.isFinite))return null;const lo=Math.min(0,...c.values),hi=Math.max(1,...c.values),py=v=>20+(hi-v)/(hi-lo)*150;return {py,baseline:py(0),width:270/c.values.length,points:c.values.map((v,i)=>`${40+(i+.5)*270/c.values.length},${py(v)}`).join(' '),lo,hi}})
</script>
<template><figure v-if="chart&&plot" class="teaching-chart"><h3>{{chart.title}}</h3><svg viewBox="0 0 340 235" role="img" :aria-label="chart.title"><line x1="40" :y1="plot.baseline" x2="310" :y2="plot.baseline" stroke="currentColor"/><text x="0" y="25">{{plot.hi}}</text><text x="0" y="170">{{plot.lo}}</text><polyline v-if="chart.style==='line'" :points="plot.points" fill="none" stroke="currentColor" stroke-width="2"/><g v-for="(v,i) in chart.values" :key="i"><rect v-if="chart.style!=='line'" :x="40+i*plot.width+8" :y="Math.min(plot.py(v),plot.baseline)" :width="Math.max(3,plot.width-16)" :height="Math.max(1,Math.abs(plot.py(v)-plot.baseline))" fill="currentColor"/><circle v-else :cx="40+(i+.5)*plot.width" :cy="plot.py(v)" r="3" fill="currentColor"/><text :x="40+(i+.5)*plot.width" :y="plot.py(v)-6" text-anchor="middle">{{v}}</text><text :x="40+(i+.5)*plot.width" y="193" text-anchor="middle">{{chart.labels[i]}}</text></g></svg></figure><figure v-else-if="diagram" class="teaching-chart"><svg v-if="diagram==='triangle'" viewBox="0 0 340 235" role="img" aria-label="直角三角形示意"><path d="M70 35 V190 H265 Z M70 170 H90 V190" fill="none" stroke="currentColor" stroke-width="2"/><text x="50" y="110">a</text><text x="155" y="215">b</text><text x="185" y="105">c</text></svg><svg v-else-if="diagram==='buoyancy'" viewBox="0 0 340 235" role="img" aria-label="浮力方向竖直向上"><rect x="40" y="95" width="260" height="110" fill="#e8eff8"/><rect x="130" y="75" width="80" height="70" fill="#d5ad7d" stroke="currentColor"/><path d="M170 110 V25 M158 40 L170 25 L182 40" fill="none" stroke="currentColor" stroke-width="3"/><text x="190" y="50">F浮</text><text x="80" y="230">浮力方向：竖直向上</text></svg></figure></template>
<style scoped>.teaching-chart{margin:0}.teaching-chart svg{display:block;width:100%;max-height:300px}.teaching-chart text{fill:currentColor;font-size:11px}</style>
